import openpyxl
ip='sheetpedia_batch1_0014_template_9201_filled.xlsx'
gp='/mnt/hhq/data/data_pipeline/generated_tasks/route_b_sheetpedia_batch1/passed/template/sheetpedia_batch1_0014_template_9201_golden.xlsx'
