nf=0; style_diffs=0; fmt_diffs=0
for si in range(len(wi.worksheets)):
    wsi=wi.worksheets[si]; wsg=wg.worksheets[si]
    for row_i, row_g in zip(wsi.iter_rows(), wsg.iter_rows()):
        for ci, cg in zip(row_i, row_g):
            vi=ci.value; vg=cg.value
            if isinstance(vi,str) and vi.startswith('='):
                nf+=1
            if ci.style_id != cg.style_id:
                style_diffs+=1
            if ci.number_format != cg.number_format:
                fmt_diffs+=1
                if fmt_diffs<20:
                    print('fmt diff', wsi.title, ci.coordinate, ci.number_format, cg.number_format)
print('formulas', nf)
print('style diffs', style_diffs, 'number_format diffs', fmt_diffs)
# Also check merged cells
for si in range(len(wi.worksheets)):
    mi=set(str(r) for r in wi.worksheets[si].merged_cells.ranges)
    mg=set(str(r) for r in wg.worksheets[si].merged_cells.ranges)
    if mi!=mg:
        print('merged diff', wi.worksheets[si].title, mi^mg)
